insert into public.products (id, category_id, name_en, name_he, description_en, description_he, tagline_en, tagline_he, image, spice_level, is_kosher, is_available, unavailable_reason, nutrition, ingredients_en, ingredients_he, allergens_en, allergens_he, sort_order) values ('biltong-traditional', 'biltong', 'Traditional', 'קלאסי', 'Air-dried beef biltong made to the original SA recipe. Spiced with coriander, black pepper, and vinegar.', 'בילטונג בקר מיובש באוויר לפי המתכון המקורי של דרום אפריקה. תובל בכוסברה, פלפל שחור וחומץ.', 'The OG. The Legend.', 'המקורי. האגדה.', '/images/biltong-720.webp', 1, true, true, null, '{"protein":"51g","fat":"8g","carbs":"1g","calories":"260"}'::jsonb, 'Premium beef, salt, coriander, black pepper, vinegar, garlic, and spices.', 'בשר בקר פרימיום, מלח, כוסברה, פלפל שחור, חומץ, שום ותבלינים.', 'May contain traces of nuts and soy.', 'עלול להכיל עקבות של אגוזים וסויה.', 0) on conflict (id) do nothing;
